const app=document.querySelector('#app');let state={token:localStorage.token||'',user:JSON.parse(localStorage.user||'null')};
if(state.user?.role==='admin'){state.user.role='superadmin';localStorage.user=JSON.stringify(state.user)}
const api=async(p,o={})=>{const r=await fetch('/api'+p,{...o,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{})}}),d=await r.json();if(!r.ok){if(r.status===401&&state.token){localStorage.clear();state={token:'',user:null};sessionStorage.setItem('sessionExpired','1');location.hash='#/login'}throw Error(d.message||'Permintaan gagal')}return d},esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0),dateLabel=value=>value?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date(value)):'—',note=(s,e=false)=>'<div class="notice '+(e?'error':'success')+'">'+esc(s)+'</div>',staff=()=>['superadmin','petugas'].includes(state.user?.role);
const loadZxing=()=>window.ZXingBrowser?Promise.resolve():new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/vendor/zxing/zxing-browser.min.js';script.onload=resolve;script.onerror=()=>reject(Error('Pemindai QR tidak dapat dimuat'));document.head.append(script)});
async function scanWithZxing(video,onCode){await loadZxing();const reader=new window.ZXingBrowser.BrowserQRCodeReader();let controls;controls=await reader.decodeFromVideoDevice(undefined,video,(result)=>{if(result){controls?.stop();onCode(result.getText())}});return controls}
function shell(body,active=''){if(!state.user)return '<header class="public-head"><a class="brand-public" href="#/catalog">📖 PustakaNusa</a><a class="btn public-login" href="#/login">Masuk</a></header><main class="wrap public-wrap">'+body+'</main>';const admin=staff(),a=state.alerts||{},badge=n=>n?'<b class="nav-badge">'+n+'</b>':'';const links=admin?'<a href="#/admin">▦ Dasbor</a><a href="#/collections">▤ Koleksi</a><a href="#/admin-loans">◷ Peminjaman '+badge(a.loans)+'</a><a class="'+(active==='complaints'?'on':'')+'" href="#/admin-complaints">✉ Pengaduan '+badge(a.complaints)+'</a>'+(state.user.role==='superadmin'?'<a class="'+(active==='members'?'on':'')+'" href="#/members"><i class="ri-user-settings-line ri-icon"></i> Kelola Akun '+badge(a.members)+'</a>':'')+'<a href="#/returns">↩ Pengembalian '+badge(a.returns)+'</a>':'<a href="#/dashboard">⌂ Beranda '+badge(state.notificationCount)+'</a><a class="'+(active==='catalog'?'on':'')+'" href="#/catalog">▤ Katalog</a><a href="#/loans">◷ Peminjaman</a><a href="#/complaints">✉ Pengaduan</a><a href="#/fines">◉ Denda '+badge(state.fineCount)+'</a>';const roleLabel={member:'Pengguna',superadmin:'Superadmin',petugas:'Petugas'}[state.user.role]||state.user.role;return '<div class="app-layout"><aside class="sidebar"><a class="brand" href="'+(admin?'#/admin':'#/dashboard')+'">📖 PustakaNusa<small>LITERASI UNTUK SEMUA</small></a><nav class="nav">'+links+'</nav><div class="sidebar-user"><b>'+esc(state.user.name)+'</b><small>'+esc(roleLabel)+'</small><button class="btn alt" id="logout">Keluar</button></div></aside><main class="wrap">'+body+'</main></div>'}
function bind(){document.querySelector('#logout')?.addEventListener('click',()=>{localStorage.clear();state={token:'',user:null};location.hash='#/catalog'})}
function login(){app.innerHTML='<section class="login"><div class="card"><a class="back-link" href="#/catalog">← Kembali ke katalog</a><h1>Selamat datang</h1><p>Masuk untuk melanjutkan.</p><form id="form"><div class="field"><label>Email</label><input id="identity" autocomplete="username" required></div><div class="field"><label>Kata sandi</label><input id="password" type="password" autocomplete="current-password" required></div><div id="feedback"></div><button class="btn" style="width:100%">Masuk</button></form><p class="muted" id="registerLink">Belum punya akun? <a href="#/register">Daftar anggota</a></p></div></section>';form.onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({identity:identity.value,password:password.value})});state={token:d.token,user:d.user};localStorage.token=d.token;localStorage.user=JSON.stringify(d.user);location.hash=staff()?'#/admin':'#/dashboard'}catch(e){feedback.innerHTML=note(e.message,true)}}}
function register(){app.innerHTML='<section class="login"><div class="card"><h1>Daftar anggota</h1><p>Akun dapat dipakai setelah disetujui admin.</p><form id="form"><div class="field"><label>Nama lengkap</label><input id="registerName" required></div><div class="field"><label>Email</label><input id="registerEmail" type="email" required></div><div class="field"><label>Telepon</label><input id="registerPhone"></div><div class="field"><label>Alamat</label><textarea id="registerAddress"></textarea></div><div class="field"><label>Kata sandi</label><input id="registerPassword" type="password" minlength="6" required></div><div id="feedback"></div><button class="btn" style="width:100%">Kirim pendaftaran</button></form><p class="muted"><a href="#/login">Kembali masuk</a></p></div></section>';const formEl=document.querySelector('#form'),feedbackEl=document.querySelector('#feedback');formEl.onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/register',{method:'POST',body:JSON.stringify({name:document.querySelector('#registerName').value,email:document.querySelector('#registerEmail').value,phone:document.querySelector('#registerPhone').value,address:document.querySelector('#registerAddress').value,password:document.querySelector('#registerPassword').value})});feedbackEl.innerHTML=note(d.message);formEl.reset()}catch(e){feedbackEl.innerHTML=note(e.message,true)}}}
async function catalog(){const cats=await api('/categories');app.innerHTML=shell('<h1>Temukan bacaan berikutnya</h1><p>Publik dapat menjelajahi katalog. Masuk sebagai anggota untuk meminjam.</p><div class="toolbar"><input id="q" placeholder="Cari judul, penulis, atau ISBN"><select id="cat"><option value="">Semua kategori</option>'+cats.map(c=>'<option value="'+c.id+'">'+esc(c.name)+' ('+c.book_count+')</option>').join('')+'</select><button class="btn" id="search">Cari</button></div><section class="grid cols-3" id="books"></section>','catalog');bind();const draw=async()=>{const b=await api('/books?q='+encodeURIComponent(q.value)+'&category='+cat.value+'&available=true');books.innerHTML=b.length?b.map(x=>'<article class="card book"><div class="cover">'+esc(x.title)+'</div><div><span class="muted">'+esc(x.category_name)+'</span><h2>'+esc(x.title)+'</h2><p>'+esc(x.author)+'</p><a class="btn" href="#/book/'+x.id+'">Detail</a></div></article>').join(''):'<div class="empty">Buku tidak ditemukan.</div>'};search.onclick=draw;await draw()}
async function book(id){const b=await api('/books/'+id),to=state.user?.role==='member'?'#/borrow/'+id:'#/login';app.innerHTML=shell('<a href="#/catalog">← Kembali</a><section class="card" style="margin-top:18px"><div class="book"><div class="cover" style="width:150px;height:220px">'+esc(b.title)+'</div><div><h1>'+esc(b.title)+'</h1><p>oleh <b>'+esc(b.author)+'</b></p><p>'+esc(b.synopsis||'Belum ada sinopsis.')+'</p><p><b>Stok:</b> '+b.stock+'</p>'+(b.stock?'<a class="btn" href="'+to+'">'+(state.user?.role==='member'?'Ajukan peminjaman':'Masuk untuk meminjam')+'</a>':'<span class="pill wait">Tidak tersedia</span>')+'</div></div></section>','catalog');bind()}
async function borrow(id){if(state.user?.role!=='member'){location.hash='#/login';return}const b=await api('/books/'+id);app.innerHTML=shell('<section class="form card"><h1>Konfirmasi peminjaman</h1><p>'+esc(b.title)+'</p><form id="form"><div class="field"><label>Lokasi pengambilan</label><input id="place" value="Perpustakaan Kota Jakarta Pusat"></div><div class="field"><label>Tanggal</label><input id="date" type="date" required></div><div id="feedback"></div><button class="btn">Ajukan</button></form></section>');bind();date.value=new Date().toISOString().slice(0,10);form.onsubmit=async e=>{e.preventDefault();try{await api('/loans',{method:'POST',body:JSON.stringify({bookId:id,pickupLocation:place.value,pickupDate:date.value,pickupTime:'10.00 – 12.00 WIB'})});location.hash='#/loans'}catch(e){feedback.innerHTML=note(e.message,true)}}}
async function dashboard(){const [d,notifications,fines]=await Promise.all([api('/dashboard'),api('/notifications'),api('/member/fines')]);state.notificationCount=notifications.length;state.fineCount=fines.length;app.innerHTML=shell('<section class="hero"><h1>Selamat datang, '+esc(state.user.name)+' 👋</h1><a class="btn alt" href="#/catalog">Jelajahi katalog</a></section><section class="grid cols-3" style="margin-top:18px"><div class="card stat"><span>Sedang dipinjam</span><b>'+d.loans.length+'</b></div><div class="card stat"><span>Denda perlu dibayar</span><b>'+money(fines.reduce((sum,x)=>sum+Number(x.amount),0))+'</b><a href="#/fines">Lihat detail denda</a></div><div class="card stat"><span>🔔 Notifikasi</span><b>'+notifications.length+'</b></div></section><section class="card" style="margin-top:18px"><h2>Deadline pengembalian</h2>'+(d.loans.length?d.loans.map(x=>'<p><b>'+esc(x.title)+'</b><br>Deadline: <b>'+dateLabel(x.due_date)+'</b><br><span class="pill wait">Lewat dari deadline akan dikenakan denda.</span></p>').join(''):'<div class="empty">Belum ada buku yang sedang dipinjam.</div>')+'</section><section class="card" style="margin-top:18px"><h2>🔔 Notifikasi</h2>'+(notifications.length?notifications.slice(0,5).map(x=>'<p>'+esc(x.message)+'</p>').join(''):'<div class="empty">Belum ada notifikasi.</div>')+'</section>');bind()}
