async function admin(){const [s,loans,alerts]=await Promise.all([api('/admin/summary'),api('/loans'),api('/admin/alerts')]);state.alerts=alerts;const groups=['menunggu','dipinjam','dikembalikan','dibatalkan'],counts=groups.map(status=>loans.filter(x=>x.status===status).length),max=Math.max(...counts,1),alertTotal=Object.values(alerts).reduce((sum,x)=>sum+Number(x),0);app.innerHTML=shell('<h1>Dasbor petugas</h1><section class="grid cols-3"><div class="card stat"><span>Koleksi</span><b>'+s.books+'</b></div><div class="card stat"><span>Anggota</span><b>'+s.members+'</b><a href="#/members">Kelola anggota</a></div><div class="card stat"><span>🔔 Notifikasi</span><b>'+alertTotal+'</b><span>'+alerts.loans+' peminjaman, '+alerts.complaints+' pengaduan baru</span></div></section><section class="card" style="margin-top:18px"><h2>Grafik status peminjaman</h2><div class="loan-chart">'+groups.map((status,i)=>'<div class="chart-item"><div class="chart-value">'+counts[i]+'</div><div class="chart-bar" style="height:'+Math.max(8,counts[i]/max*150)+'px"></div><span>'+status+'</span></div>').join('')+'</div></section>');bind()}
async function finesLegacy(){const rows=await api('/member/fines');state.fineCount=rows.length;app.innerHTML=shell('<h1>Denda</h1><p>Bayar denda melalui QRIS atau Virtual Account BCA.</p><section class="card"><table><thead><tr><th>Jenis</th><th>Detail</th><th>Nominal</th><th>Pembayaran</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(x.source_type==='loan'?'Peminjaman':'Pengaduan')+'</td><td>'+esc(x.label)+'</td><td>'+money(x.amount)+'</td><td><button class="btn pay" data-type="'+x.source_type+'" data-id="'+x.source_id+'" data-method="qris">QRIS</button> <button class="btn alt pay" data-type="'+x.source_type+'" data-id="'+x.source_id+'" data-method="va_bca">VA BCA</button></td></tr>').join('')||'<tr><td colspan="4" class="empty">Tidak ada denda yang perlu dibayar.</td></tr>'+'</tbody></table></section>','fines');bind();document.querySelectorAll('.pay').forEach(b=>b.onclick=async()=>{try{await api('/member/fines/'+b.dataset.type+'/'+b.dataset.id+'/pay',{method:'POST',body:JSON.stringify({method:b.dataset.method})});alert('Pembayaran '+(b.dataset.method==='qris'?'QRIS':'VA BCA')+' berhasil dicatat.');fines()}catch(e){alert(e.message)}})}
async function adminComplaintsLegacy(){const r=await api('/complaints');app.innerHTML=shell('<h1>Pengaduan anggota</h1><p>Klik data pengaduan untuk melihat detail dan input denda.</p><section class="card"><table><thead><tr><th>Anggota</th><th>Buku</th><th>Jenis</th><th>Status</th><th>Denda</th></tr></thead><tbody>'+r.map(x=>'<tr class="click-row comp" data-id="'+x.id+'"><td>'+esc(x.member_name)+'</td><td>'+esc(x.book_title||'—')+'</td><td>'+esc(x.type)+'</td><td>'+esc(x.status)+'</td><td>'+money(x.fine_amount)+'</td></tr>').join('')+'</tbody></table></section><div id="detail"></div>','complaints');bind();document.querySelectorAll('.comp').forEach(e=>e.onclick=()=>{const x=r.find(y=>String(y.id)===e.dataset.id),can=['Buku rusak','Buku hilang'].includes(x.type),fineValue=Number(x.fine_amount||0);detail.innerHTML='<section class="card detail-card"><div class="row"><h2>Detail pengaduan</h2><button class="btn danger" id="deleteComplaint">Hapus</button></div><p><b>'+esc(x.member_name)+'</b> · '+esc(x.type)+'</p><p><b>Buku:</b> '+esc(x.book_title||'—')+'</p><p>'+esc(x.description)+'</p>'+(can?'<form id="fineForm"><div class="field"><label>Nominal denda</label><input id="amount" type="number" min="0" step="1" value="'+(fineValue||'')+'" placeholder="Masukkan nominal denda"></div><div id="feedback"></div><button class="btn">Simpan denda</button></form>':'<p class="muted">Tidak ada denda untuk jenis pengaduan ini.</p>')+'</section>';deleteComplaint.onclick=async()=>{if(!confirm('Hapus pengaduan ini?'))return;try{await api('/complaints/'+x.id,{method:'DELETE'});adminComplaints()}catch(z){alert(z.message)}};document.querySelector('#fineForm')?.addEventListener('submit',async z=>{z.preventDefault();try{await api('/complaints/'+x.id,{method:'PATCH',body:JSON.stringify({status:'selesai',fineAmount:amount.value})});adminComplaints()}catch(z){feedback.innerHTML=note(z.message,true)}})})}
async function membersLegacy(){const r=await api('/admin/members');app.innerHTML=shell('<div class="row"><div><h1>Kelola anggota</h1><p>Data anggota dan persetujuan pendaftaran.</p></div><button class="btn" id="new">+ Tambah</button></div><form id="form" class="card" hidden><h2 id="formTitle">Tambah anggota</h2><div class="field"><label>Nama</label><input id="memberName" required></div><div class="field"><label>Email</label><input id="memberEmail" type="email" required></div><div class="field"><label>Telepon</label><input id="memberPhone"></div><div class="field"><label>Alamat</label><input id="memberAddress"></div><div class="field" id="passField"><label>Kata sandi</label><input id="memberPassword" type="password" minlength="6"></div><div id="feedback"></div><button class="btn">Simpan</button></form><section class="card" style="margin-top:18px"><table><thead><tr><th>No</th><th>Nama</th><th>Email</th><th>Status</th><th>Aksi</th></tr></thead><tbody>'+r.map(x=>'<tr><td>'+esc(x.member_no)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.email)+'</td><td>'+esc(x.registration_status)+'</td><td class="actions">'+(x.registration_status==='menunggu'?'<button class="btn approve" data-id="'+x.id+'">ACC</button> <button class="btn danger reject" data-id="'+x.id+'">Tolak</button> ':'')+'<button class="btn alt edit" data-id="'+x.id+'">Ubah</button> <button class="btn danger del" data-id="'+x.id+'">Hapus</button></td></tr>').join('')+'</tbody></table></section>','members');bind();const formEl=document.querySelector('#form'),nameEl=document.querySelector('#memberName'),emailEl=document.querySelector('#memberEmail'),phoneEl=document.querySelector('#memberPhone'),addressEl=document.querySelector('#memberAddress'),passwordEl=document.querySelector('#memberPassword'),feedbackEl=document.querySelector('#feedback');let id;document.querySelector('#new').onclick=()=>{id=null;formEl.reset();formEl.hidden=false;passField.hidden=false;passwordEl.required=true;formTitle.textContent='Tambah anggota'};formEl.onsubmit=async e=>{e.preventDefault();try{await api(id?'/admin/members/'+id:'/admin/members',{method:id?'PATCH':'POST',body:JSON.stringify({name:nameEl.value,email:emailEl.value,phone:phoneEl.value,address:addressEl.value,password:passwordEl.value})});members()}catch(e){feedbackEl.innerHTML=note(e.message,true)}};document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{const x=r.find(y=>y.id==b.dataset.id);id=x.id;nameEl.value=x.name;emailEl.value=x.email;phoneEl.value=x.phone||'';addressEl.value=x.address||'';formEl.hidden=false;passField.hidden=true;passwordEl.required=false;formTitle.textContent='Ubah anggota'});const status=(i,s)=>api('/admin/members/'+i+'/registration',{method:'PATCH',body:JSON.stringify({status:s})}).then(members).catch(e=>alert(e.message));document.querySelectorAll('.approve').forEach(b=>b.onclick=()=>status(b.dataset.id,'disetujui'));document.querySelectorAll('.reject').forEach(b=>b.onclick=()=>status(b.dataset.id,'ditolak'));document.querySelectorAll('.del').forEach(b=>b.onclick=async()=>{if(confirm('Hapus anggota ini?'))try{await api('/admin/members/'+b.dataset.id,{method:'DELETE'});members()}catch(e){alert(e.message)}})}
async function adminLoansLegacy(){const all=await api('/loans'),r=all.filter(x=>x.status==='menunggu'),today=new Date().toISOString().slice(0,10);app.innerHTML=shell('<h1>Persetujuan peminjaman</h1><p>Tetapkan deadline pengembalian sebelum menyetujui pengajuan.</p><section class="card"><table><thead><tr><th>Anggota</th><th>Buku</th><th>Tanggal ambil</th><th>Deadline pengembalian</th><th>Keputusan</th></tr></thead><tbody>'+r.map(x=>'<tr><td>'+esc(x.member_name)+'</td><td>'+esc(x.books)+'</td><td>'+dateLabel(x.pickup_date)+'</td><td><input class="deadline" data-id="'+x.id+'" type="date" min="'+esc(x.pickup_date||today)+'" required></td><td><button class="btn rev" data-id="'+x.id+'" data-a="approve">ACC</button> <button class="btn danger rev" data-id="'+x.id+'" data-a="reject">Tolak</button></td></tr>').join('')+'</tbody></table></section><section class="card" style="margin-top:18px"><h2>Riwayat peminjaman</h2><table><thead><tr><th>Anggota</th><th>Buku</th><th>Status</th><th>Deadline</th><th></th></tr></thead><tbody>'+all.filter(x=>x.status!=='menunggu').map(x=>'<tr><td>'+esc(x.member_name)+'</td><td>'+esc(x.books)+'</td><td>'+esc(x.status)+'</td><td>'+dateLabel(x.due_date)+'</td><td><button class="btn danger deleteLoan" data-id="'+x.id+'">Hapus</button></td></tr>').join('')+'</tbody></table></section>');bind();document.querySelectorAll('.rev').forEach(b=>b.onclick=async()=>{try{const dueDate=document.querySelector('.deadline[data-id="'+b.dataset.id+'"]')?.value;if(b.dataset.a==='approve'&&!dueDate){alert('Isi deadline pengembalian terlebih dahulu.');return}await api('/loans/'+b.dataset.id+'/review',{method:'PATCH',body:JSON.stringify({action:b.dataset.a,dueDate})});adminLoans()}catch(e){alert(e.message)}});document.querySelectorAll('.deleteLoan').forEach(b=>b.onclick=()=>removeLoan(b.dataset.id,adminLoans))}
async function collections(){const [r,cats]=await Promise.all([api('/books'),api('/categories')]);app.innerHTML=shell('<div class="row"><div><h1>Daftar koleksi</h1><p>Tambah, ubah, atau hapus buku.</p></div><button class="btn" id="newBook">+ Tambah buku</button></div><form id="bookForm" class="card" hidden style="margin-top:18px"><h2 id="bookTitle">Tambah buku</h2><div class="grid cols-2"><div class="field"><label>Judul</label><input id="bookName" required></div><div class="field"><label>Penulis</label><input id="bookAuthor" required></div><div class="field"><label>Kategori</label><select id="bookCategory">'+cats.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></div><div class="field"><label>Stok</label><input id="bookStock" type="number" min="0" value="1" required></div><div class="field"><label>Penerbit</label><input id="bookPublisher"></div><div class="field"><label>Tahun terbit</label><input id="bookYear" type="number" min="0"></div><div class="field"><label>ISBN</label><input id="bookIsbn"></div><div class="field"><label>Harga</label><input id="bookPrice" type="number" min="0" value="0"></div></div><div class="field"><label>Sinopsis</label><textarea id="bookSynopsis"></textarea></div><div id="feedback"></div><button class="btn">Simpan buku</button></form><section class="card" style="margin-top:18px"><table><thead><tr><th>Judul</th><th>Penulis</th><th>Kategori</th><th>Stok</th><th>Aksi</th></tr></thead><tbody>'+r.map(x=>'<tr><td>'+esc(x.title)+'</td><td>'+esc(x.author)+'</td><td>'+esc(x.category_name)+'</td><td>'+x.stock+'</td><td><button class="btn alt editBook" data-id="'+x.id+'">Ubah</button> <button class="btn danger deleteBook" data-id="'+x.id+'">Hapus</button></td></tr>').join('')+'</tbody></table></section>','collections');bind();const formEl=document.querySelector('#bookForm'),value=id=>document.querySelector(id),feedbackEl=value('#feedback');let id;newBook.onclick=()=>{id=null;formEl.reset();bookStock.value=1;bookPrice.value=0;bookTitle.textContent='Tambah buku';formEl.hidden=false};formEl.onsubmit=async e=>{e.preventDefault();const p={title:value('#bookName').value,author:value('#bookAuthor').value,categoryId:value('#bookCategory').value,stock:value('#bookStock').value,publisher:value('#bookPublisher').value,publishedYear:value('#bookYear').value,isbn:value('#bookIsbn').value,price:value('#bookPrice').value,synopsis:value('#bookSynopsis').value};try{await api(id?'/admin/books/'+id:'/admin/books',{method:id?'PATCH':'POST',body:JSON.stringify(p)});collectionsV2()}catch(e){feedbackEl.innerHTML=note(e.message,true)}};document.querySelectorAll('.editBook').forEach(b=>b.onclick=()=>{const x=r.find(y=>y.id==b.dataset.id);id=x.id;bookName.value=x.title;bookAuthor.value=x.author;bookCategory.value=x.category_id;bookStock.value=x.stock;bookPublisher.value=x.publisher||'';bookYear.value=x.published_year||'';bookIsbn.value=x.isbn||'';bookPrice.value=x.price||0;bookSynopsis.value=x.synopsis||'';bookTitle.textContent='Ubah buku';formEl.hidden=false});document.querySelectorAll('.deleteBook').forEach(b=>b.onclick=async()=>{if(!confirm('Hapus buku ini?'))return;try{await api('/admin/books/'+b.dataset.id,{method:'DELETE'});collectionsV2()}catch(e){alert(e.message)}})}
