async function returnsLegacy(){const r=await api('/loans'),active=r.filter(x=>['dipinjam','terlambat'].includes(x.status)),returned=r.filter(x=>x.status==='dikembalikan');app.innerHTML=shell('<h1>Pengembalian buku</h1><section class="card"><h2>Menunggu validasi pengembalian</h2><table><thead><tr><th>Peminjam</th><th>Buku</th><th>Deadline</th><th></th></tr></thead><tbody>'+(active.map(x=>'<tr><td>'+esc(x.member_name)+'</td><td>'+esc(x.books)+'</td><td>'+dateLabel(x.due_date)+'</td><td><button class="btn ret" data-id="'+x.id+'">Validasi kembali</button></td></tr>').join('')||'<tr><td colspan="4" class="empty">Tidak ada buku yang perlu dikembalikan.</td></tr>')+'</tbody></table></section><section class="card" style="margin-top:18px"><h2>Data buku sudah dikembalikan</h2><table><thead><tr><th>Peminjam</th><th>Buku</th><th>Tanggal pinjam</th><th>Deadline</th><th>Dikembalikan</th><th>Denda</th><th></th></tr></thead><tbody>'+(returned.map(x=>'<tr><td>'+esc(x.member_name)+'</td><td>'+esc(x.books)+'</td><td>'+dateLabel(x.loan_date)+'</td><td>'+dateLabel(x.due_date)+'</td><td>'+dateLabel(x.returned_date)+'</td><td>'+money(x.fine_total)+'</td><td><button class="btn danger deleteLoan" data-id="'+x.id+'">Hapus</button></td></tr>').join('')||'<tr><td colspan="7" class="empty">Belum ada buku yang dikembalikan.</td></tr>')+'</tbody></table></section>');bind();document.querySelectorAll('.ret').forEach(b=>b.onclick=async()=>{try{await api('/loans/'+b.dataset.id+'/return',{method:'POST',body:'{}'});returns()}catch(e){alert(e.message)}});document.querySelectorAll('.deleteLoan').forEach(b=>b.onclick=()=>removeLoan(b.dataset.id,returns))}
async function route(){const [p,id]=location.hash.slice(2).split('/');try{if(p==='login')return login();if(p==='register')return register();if(!p||p==='catalog')return catalog();if(p==='book')return book(id);if(p==='borrow')return borrow(id);if(!state.user){location.hash='#/login';return}if(p==='dashboard')return dashboard();if(p==='fines')return fines();if(p==='loans')return loans();if(p==='complaints')return memberComplaints();if(p==='admin')return admin();if(p==='admin-complaints')return adminComplaints();if(p==='members'&&state.user.role==='superadmin')return members();if(p==='admin-loans')return adminLoans();if(p==='collections')return collections();if(p==='returns')return returns();location.hash=staff()?'#/admin':'#/dashboard'}catch(e){app.innerHTML='<section class="form card"><h1>Terjadi kendala</h1>'+note(e.message,true)+'</section>'}}addEventListener('hashchange',route);route();
const remixIcons={'📖':'ri-book-3-line','▦':'ri-dashboard-line','▤':'ri-book-shelf-line','◷':'ri-time-line','✉':'ri-mail-line','♙':'ri-user-line','↩':'ri-arrow-go-back-line','⌂':'ri-home-4-line','◉':'ri-money-dollar-circle-line','🔔':'ri-notification-3-line','←':'ri-arrow-left-line','👋':'ri-hand-heart-line'};function replaceEmojiIcons(root=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{let value=node.nodeValue;if(!Object.keys(remixIcons).some(icon=>value.includes(icon)))return;const fragment=document.createDocumentFragment();for(const part of value.split(/(📖|▦|▤|◷|✉|♙|↩|⌂|◉|🔔|←|👋)/)){if(remixIcons[part]){const icon=document.createElement('i');icon.className=remixIcons[part]+' ri-icon';fragment.append(icon)}else if(part)fragment.append(document.createTextNode(part))}node.replaceWith(fragment)})}replaceEmojiIcons();new MutationObserver(()=>replaceEmojiIcons()).observe(document.body,{childList:true,subtree:true});
async function mountNotificationsLegacy(){if(!state.user||document.querySelector('#notificationBell'))return;const wrap=document.querySelector('.wrap'),hero=document.querySelector('.hero'),target=hero||wrap;if(!target)return;const bell=document.createElement('div');bell.id='notificationBell';bell.className='notification-area';bell.innerHTML='<button class="notification-button" aria-label="Notifikasi"><i class="ri-notification-3-line"></i><span class="notification-badge" hidden>0</span></button><div class="notification-panel" hidden><div class="notification-head"><b>Notifikasi</b><button class="notification-close" aria-label="Tutup">×</button></div><div class="notification-list"><div class="empty">Memuat notifikasi...</div></div></div>';target.append(bell);if(hero)removeDashboardNotificationCards();const list=bell.querySelector('.notification-list'),badge=bell.querySelector('.notification-badge');try{const rows=await api(staff()?'/admin/notifications':'/notifications');badge.textContent=rows.length;badge.hidden=!rows.length;list.innerHTML=rows.length?rows.map(x=>'<div class="notification-item"><b>'+esc(x.title||'Notifikasi')+'</b><span>'+esc(x.message)+'</span><small>'+dateLabel(x.created_at)+'</small></div>').join(''):'<div class="empty">Belum ada notifikasi baru.</div>'}catch(e){list.innerHTML='<div class="empty">Notifikasi tidak dapat dimuat.</div>'}const panel=bell.querySelector('.notification-panel');bell.querySelector('.notification-button').onclick=e=>{e.stopPropagation();panel.hidden=!panel.hidden};bell.querySelector('.notification-close').onclick=()=>{panel.hidden=true};document.addEventListener('click',e=>{if(!bell.contains(e.target))panel.hidden=true})}mountNotifications();new MutationObserver(()=>mountNotifications()).observe(document.body,{childList:true,subtree:true});
