async function adminComplaints(){const rows=await api('/complaints'),active=rows.filter(x=>x.status!=='selesai'),history=rows.filter(x=>x.status==='selesai');app.innerHTML=shell('<h1>Pengaduan anggota</h1><p>Pengaduan selesai dan sudah ditetapkan dendanya dipindahkan ke riwayat.</p><div class="history-actions"><button class="btn alt history-toggle" id="complaintHistory"><i class="ri-history-line"></i> Riwayat pengaduan</button></div><section class="card" id="activeComplaints"><h2>Pengaduan perlu ditangani</h2>'+complaintTable(active,'Tidak ada pengaduan yang perlu ditangani.')+'</section><section class="card" id="complaintHistoryTable" hidden><h2>Riwayat pengaduan</h2>'+complaintTable(history,'Belum ada riwayat pengaduan.')+'</section><div id="complaintModal" class="complaint-modal" hidden></div>','complaints');bind();const modal=document.querySelector('#complaintModal'),activeTable=document.querySelector('#activeComplaints'),historyTable=document.querySelector('#complaintHistoryTable'),toggle=document.querySelector('#complaintHistory'),close=()=>{modal.hidden=true;modal.innerHTML=''};toggle.onclick=()=>{const show=historyTable.hidden;historyTable.hidden=!show;activeTable.hidden=show;toggle.innerHTML=show?'<i class="ri-arrow-go-back-line"></i> Pengaduan aktif':'<i class="ri-history-line"></i> Riwayat pengaduan'};modal.onclick=e=>{if(e.target===modal)close()};document.querySelectorAll('.comp').forEach(row=>row.onclick=()=>{const x=rows.find(y=>String(y.id)===row.dataset.id),fineValue=Number(x.fine_amount||0),paid=x.payment_status==='dibayar',finished=x.status==='selesai';modal.innerHTML='<section class="card complaint-modal-card"><div class="row"><h2>Detail pengaduan</h2><div><button class="btn danger" id="deleteComplaint">Hapus</button><button class="icon-button" id="closeComplaintModal" aria-label="Tutup"><i class="ri-close-line"></i></button></div></div><p><b>'+esc(x.member_name)+'</b> · '+esc(x.type)+'</p><p><b>Buku:</b> '+esc(x.book_title||'—')+'</p><p>'+esc(x.description)+'</p><form id="fineForm"><div class="field"><label>Nominal denda</label><input id="amount" type="number" min="0" step="1" value="'+(fineValue||'')+'" '+(paid?'disabled':'')+' placeholder="Masukkan nominal denda"></div><div class="field"><label>Jatuh tempo pembayaran</label><input id="dueDate" type="date" value="'+(x.fine_due_date?String(x.fine_due_date).slice(0,10):'')+'" '+(paid?'disabled':'')+'></div>'+(paid?'<p class="pill">Sudah dibayar</p>':finished?'<p class="muted">Pengaduan sudah masuk riwayat. Tagihan tetap tersedia di Pembayaran Denda.</p>':'<p class="muted">Saat disimpan, pengaduan masuk riwayat dan tagihan muncul di Pembayaran Denda pengguna.</p>')+'<div id="feedback"></div><button class="btn" '+(paid?'disabled':'')+'>'+ (finished?'Perbarui denda':'Simpan denda & kirim tagihan') +'</button></form></section>';modal.hidden=false;modal.querySelector('#closeComplaintModal').onclick=close;modal.querySelector('#deleteComplaint').onclick=async()=>{if(!confirm('Hapus pengaduan ini?'))return;try{await api('/complaints/'+x.id,{method:'DELETE'});close();adminComplaints()}catch(e){alert(e.message)}};modal.querySelector('#fineForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/complaints/'+x.id,{method:'PATCH',body:JSON.stringify({status:'selesai',fineAmount:modal.querySelector('#amount').value,dueDate:modal.querySelector('#dueDate').value})});close();adminComplaints()}catch(e){modal.querySelector('#feedback').innerHTML=note(e.message,true)}})})}
async function paymentsV2InteractiveLegacy(){const rows=await api('/admin/fine-payments');const wa=x=>{const number=String(x.phone||'').replace(/\\D/g,'').replace(/^0/,'62');if(!number)return '<span class="muted">Nomor telepon belum ada</span>';const text=encodeURIComponent('Halo '+x.member_name+', tagihan denda '+x.label+' sebesar '+money(x.amount)+' telah melewati jatuh tempo. Mohon segera melakukan pembayaran.');return '<a class="btn alt wa-link" target="_blank" rel="noopener" href="https://wa.me/'+number+'?text='+text+'"><i class="ri-whatsapp-line"></i> Hubungi</a>'};app.innerHTML=shell('<h1>Pembayaran denda</h1><p>Seluruh tagihan aktif dan pembayaran yang telah dicatat.</p><section class="card"><div class="table-scroll"><table><thead><tr><th>Anggota</th><th>Tagihan</th><th>Nominal</th><th>Jatuh tempo</th><th>Status</th><th>Metode</th><th>Tindakan</th></tr></thead><tbody>'+(rows.length?rows.map(x=>'<tr><td><b>'+esc(x.member_name)+'</b><br><span class="muted">'+esc(x.member_no)+'</span></td><td>'+esc(x.source_type==='loan'?'Peminjaman':'Pengaduan')+'<br><span class="muted">'+esc(x.label||'—')+'</span></td><td>'+money(x.amount)+'</td><td>'+dateLabel(x.due_date)+(x.status==='menunggu'&&Number(x.days_left)<0?'<br><span class="fine-overdue">Terlambat '+Math.abs(Number(x.days_left))+' hari</span>':'')+'</td><td><span class="pill '+(x.status==='dibayar'?'':'wait')+'">'+esc(x.status==='dibayar'?'Dibayar':'Belum dibayar')+'</span></td><td>'+esc(paymentMethodLabel(x.method))+'</td><td>'+(x.status==='menunggu'&&Number(x.days_left)<0?wa(x):'—')+'</td></tr>').join(''):'<tr><td colspan="7" class="empty">Belum ada tagihan atau pembayaran denda.</td></tr>')+'</tbody></table></div></section>');bind()}
async function paymentsV2(){const rows=await api('/admin/fine-payments');const overdue=x=>x.status==='menunggu'&&Number(x.days_left)<0,wa=x=>{const number=String(x.phone||'').replace(/\D/g,'').replace(/^0/,'62');if(!number)return '<span class="muted">Nomor telepon belum ada</span>';const text=encodeURIComponent('Halo '+x.member_name+', tagihan denda '+x.label+' sebesar '+money(x.amount)+' telah melewati jatuh tempo. Mohon segera melakukan pembayaran.');return '<a class="btn alt wa-link" target="_blank" rel="noopener" href="https://wa.me/'+number+'?text='+text+'"><i class="ri-whatsapp-line"></i> Hubungi</a>'};app.innerHTML=shell('<h1>Pembayaran denda</h1><p>Klik data pembayaran untuk melihat detail atau menghapusnya.</p><section class="card"><div class="table-scroll"><table><thead><tr><th>Anggota</th><th>Tagihan</th><th>Nominal</th><th>Jatuh tempo</th><th>Status</th><th>Metode</th><th>Tindakan</th></tr></thead><tbody>'+(rows.length?rows.map(x=>'<tr class="click-row payment-row" data-id="'+x.id+'"><td><b>'+esc(x.member_name)+'</b><br><span class="muted">'+esc(x.member_no)+'</span></td><td>'+esc(x.source_type==='loan'?'Peminjaman':'Pengaduan')+'<br><span class="muted">'+esc(x.label||'—')+'</span></td><td>'+money(x.amount)+'</td><td>'+dateLabel(x.due_date)+(overdue(x)?'<br><span class="fine-overdue">Terlambat '+Math.abs(Number(x.days_left))+' hari</span>':'')+'</td><td><span class="pill '+(x.status==='dibayar'?'':'wait')+'">'+esc(x.status==='dibayar'?'Dibayar':'Belum dibayar')+'</span></td><td>'+esc(paymentMethodLabel(x.method))+'</td><td>'+(overdue(x)?wa(x):'—')+'</td></tr>').join(''):'<tr><td colspan="7" class="empty">Belum ada tagihan atau pembayaran denda.</td></tr>')+'</tbody></table></div></section><div id="paymentModal" class="complaint-modal" hidden></div>');bind();const modal=document.querySelector('#paymentModal'),close=()=>{modal.hidden=true;modal.innerHTML=''};modal.onclick=e=>{if(e.target===modal)close()};document.querySelectorAll('.payment-row').forEach(row=>row.onclick=e=>{if(e.target.closest('.wa-link'))return;const x=rows.find(item=>String(item.id)===row.dataset.id);modal.innerHTML='<section class="card complaint-modal-card"><div class="row"><h2>Detail pembayaran denda</h2><div><button class="btn danger" id="deletePayment">Hapus</button><button class="icon-button" id="closePaymentModal" aria-label="Tutup"><i class="ri-close-line"></i></button></div></div><dl class="payment-detail"><div><dt>Anggota</dt><dd>'+esc(x.member_name)+' · '+esc(x.member_no)+'</dd></div><div><dt>Tagihan</dt><dd>'+esc(x.source_type==='loan'?'Peminjaman':'Pengaduan')+' — '+esc(x.label||'—')+'</dd></div><div><dt>Nominal</dt><dd>'+money(x.amount)+'</dd></div><div><dt>Jatuh tempo</dt><dd>'+dateLabel(x.due_date)+'</dd></div><div><dt>Status</dt><dd>'+esc(x.status==='dibayar'?'Dibayar':'Belum dibayar')+'</dd></div><div><dt>Metode pembayaran</dt><dd>'+esc(paymentMethodLabel(x.method)||'Belum dipilih')+'</dd></div><div><dt>Waktu pembayaran</dt><dd>'+dateLabel(x.paid_at||x.created_at)+'</dd></div></dl></section>';modal.hidden=false;modal.querySelector('#closePaymentModal').onclick=close;modal.querySelector('#deletePayment').onclick=async()=>{if(!confirm('Hapus data pembayaran denda ini?'))return;try{await api('/admin/fine-payments/'+x.id,{method:'DELETE'});close();paymentsV2()}catch(err){alert(err.message)}}})}
async function membersAccountsLegacy(){const rows=await api('/admin/accounts');app.innerHTML=shell('<div class="row"><div><h1>Kelola akun</h1><p>Tambahkan akun Petugas atau Pengguna.</p></div><button class="btn" id="newAccount"><i class="ri-add-line"></i> Tambah akun</button></div><form id="accountForm" class="card" hidden><h2>Tambah akun</h2><div class="field"><label>Role</label><select id="accountRole"><option value="member">Pengguna</option><option value="petugas">Petugas</option></select></div><div class="field"><label>Nama</label><input id="accountName" required></div><div class="field"><label>Email</label><input id="accountEmail" type="email" required></div><div class="field"><label>Telepon</label><input id="accountPhone"></div><div class="field" id="accountAddressField"><label>Alamat</label><input id="accountAddress"></div><div class="field"><label>Kata sandi</label><input id="accountPassword" type="password" minlength="6" required></div><div id="accountFeedback"></div><button class="btn">Simpan akun</button></form><section class="card" style="margin-top:18px"><div class="table-scroll"><table><thead><tr><th>No</th><th>Nama</th><th>Email</th><th>Role</th><th>Telepon</th><th>Alamat</th><th>Status</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(x.member_no||'—')+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.email||'—')+'</td><td><span class="pill '+(x.role==='superadmin'?'':'wait')+'">'+esc(x.role==='member'?'Pengguna':x.role==='superadmin'?'Superadmin':'Petugas')+'</span></td><td>'+esc(x.phone||'—')+'</td><td class="member-address">'+esc(x.address||'—')+'</td><td>'+esc(x.status)+'</td></tr>').join('')+'</tbody></table></div></section>','members');bind();const form=document.querySelector('#accountForm'),role=document.querySelector('#accountRole'),addressField=document.querySelector('#accountAddressField'),phone=document.querySelector('#accountPhone'),address=document.querySelector('#accountAddress');const syncRole=()=>{const member=role.value==='member';addressField.hidden=!member;phone.closest('.field').hidden=!member};document.querySelector('#newAccount').onclick=()=>{form.reset();syncRole();form.hidden=false};role.onchange=syncRole;form.onsubmit=async e=>{e.preventDefault();try{await api('/admin/accounts',{method:'POST',body:JSON.stringify({role:role.value,name:accountName.value,email:accountEmail.value,password:accountPassword.value,phone:phone.value,address:address.value})});members()}catch(e){accountFeedback.innerHTML=note(e.message,true)}}}
