  const rows=accounts.map(account=>`<tr class="click-row account-row" data-type="${account.account_type}" data-id="${account.id}"><td>${esc(account.member_no||'—')}</td><td>${esc(account.name)}</td><td>${esc(account.email||'—')}</td><td><span class="pill ${account.role==='superadmin'?'':'wait'}">${label(account.role)}</span></td><td>${esc(account.phone||'—')}</td><td class="member-address">${esc(account.address||'—')}</td><td>${esc(account.status)}</td></tr>`).join('');
