  bind();
  const createForm=document.querySelector('#accountForm');
  const createRole=document.querySelector('#accountRole');
  const syncCreate=()=>document.querySelectorAll('.member-create').forEach(field=>field.hidden=createRole.value!=='member');
  document.querySelector('#newAccount').onclick=()=>{createForm.reset();syncCreate();createForm.hidden=false};
  createRole.onchange=syncCreate;
  createForm.onsubmit=async event=>{event.preventDefault();try{await api('/admin/accounts',{method:'POST',body:JSON.stringify({role:createRole.value,name:document.querySelector('#accountName').value,email:document.querySelector('#accountEmail').value,password:document.querySelector('#accountPassword').value,phone:document.querySelector('#accountPhone').value,address:document.querySelector('#accountAddress').value})});members()}catch(error){document.querySelector('#accountFeedback').innerHTML=note(error.message,true)}};
  const modal=document.querySelector('#accountModal');
  const close=()=>{modal.hidden=true;modal.innerHTML=''};
  modal.onclick=event=>{if(event.target===modal)close()};
  document.querySelectorAll('.account-row').forEach(row=>row.onclick=()=>{
    const account=accounts.find(item=>item.account_type===row.dataset.type&&String(item.id)===row.dataset.id);
    const isMember=account.account_type==='member';
    modal.innerHTML=`<section class="card complaint-modal-card"><div class="row"><h2>Kelola akun</h2><div>${account.role==='superadmin'?'':'<button class="btn danger" id="deleteAccount">Hapus</button>'}<button class="icon-button" id="closeAccountModal" aria-label="Tutup"><i class="ri-close-line"></i></button></div></div><form id="editAccountForm"><div class="field"><label>Role</label><select id="editRole">${accountRoleOptionsV2(account)}</select></div><div class="field"><label>Nama</label><input id="editName" required value="${esc(account.name)}"></div><div class="field"><label>Email</label><input id="editEmail" type="email" required value="${esc(account.email||'')}"></div>${isMember?`<div class="field"><label>Telepon</label><input id="editPhone" value="${esc(account.phone||'')}"></div><div class="field"><label>Alamat</label><input id="editAddress" value="${esc(account.address||'')}"></div>`:''}<div id="editFeedback"></div><button class="btn">Simpan perubahan</button></form></section>`;
    modal.hidden=false;
    modal.querySelector('#closeAccountModal').onclick=close;
    modal.querySelector('#editAccountForm').onsubmit=async event=>{event.preventDefault();const feedback=modal.querySelector('#editFeedback');try{await api(`/admin/accounts/${account.account_type}/${account.id}`,{method:'PATCH',body:JSON.stringify({name:modal.querySelector('#editName').value,email:modal.querySelector('#editEmail').value,phone:modal.querySelector('#editPhone')?.value||'',address:modal.querySelector('#editAddress')?.value||''})});const role=modal.querySelector('#editRole').value;if(role!==account.role)await api(`/admin/accounts/${account.account_type}/${account.id}/role`,{method:'PATCH',body:JSON.stringify({role})});close();members()}catch(error){feedback.innerHTML=note(error.message,true)}};
    modal.querySelector('#deleteAccount')?.addEventListener('click',async()=>{if(!confirm(`Hapus akun ${account.name}?`))return;try{await api(`/admin/accounts/${account.account_type}/${account.id}`,{method:'DELETE'});close();members()}catch(error){modal.querySelector('#editFeedback').innerHTML=note(error.message,true)}});
  });
